import{_ as n,o as r,c as a,ah as i}from"./chunks/framework.DDXs_i7t.js";const l=JSON.parse('{"title":"Die Hydra der Macht: Die Zangenbewegung gegen den Kronzeugen","description":"Wie die Anwaltsteams von Kurz und Dichand (Rami & Suppan) versuchen, Thomas Schmid juristisch zu zerquetschen.","frontmatter":{"title":"Die Hydra der Macht: Die Zangenbewegung gegen den Kronzeugen","description":"Wie die Anwaltsteams von Kurz und Dichand (Rami & Suppan) versuchen, Thomas Schmid juristisch zu zerquetschen.","date":"2026-04-07T00:00:00.000Z"},"headers":[],"relativePath":"logbuch/2026-04-07-hydra-of-power-pincer-movement.md","filePath":"logbuch/2026-04-07-hydra-of-power-pincer-movement.md"}'),t={name:"logbuch/2026-04-07-hydra-of-power-pincer-movement.md"};function s(h,e,d,u,g,o){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="die-hydra-der-macht-die-zangenbewegung-gegen-den-kronzeugen" tabindex="-1">Die Hydra der Macht: Die Zangenbewegung gegen den Kronzeugen <a class="header-anchor" href="#die-hydra-der-macht-die-zangenbewegung-gegen-den-kronzeugen" aria-label="Permalink to &quot;Die Hydra der Macht: Die Zangenbewegung gegen den Kronzeugen&quot;">​</a></h1><p><strong>Wien, 7. April 2026</strong> – Während unser Viralitäts-Index die 500.000er-Marke überschreitet, formiert sich in der juristischen Realität eine Zangenbewegung, die wir in unserem Projekt als <strong>„Hydra der Macht“</strong> bezeichnen.</p><p>Es geht nicht mehr nur um einzelne Klagen, sondern um eine koordinierte Vernichtungsstrategie gegen den Kronzeugen Thomas Schmid.</p><h2 id="die-zwei-kopfe-der-hydra" tabindex="-1">Die zwei Köpfe der Hydra <a class="header-anchor" href="#die-zwei-kopfe-der-hydra" aria-label="Permalink to &quot;Die zwei Köpfe der Hydra&quot;">​</a></h2><p>Zwei prominente Anwaltsteams agieren derzeit parallel, um das Fundament der Korruptionsermittlungen zu untergraben:</p><ol><li><strong>Der statistische Kopf (Michael Rami / Eva Dichand):</strong> In der Inseraten-Causa wird mit einer WU-Studie versucht, Schmids Aussagen über „wohlwollende Berichterstattung“ als mathematisch unmöglich darzustellen. Es ist der Versuch, Korruption durch Algorithmen wegzurechnen.</li><li><strong>Der strafrechtliche Kopf (Werner Suppan / Sebastian Kurz):</strong> Im Postenschacher-Prozess (Fall Wöginger) hat Kurz nun eine Anzeige wegen Falschaussage gegen Schmid eingebracht. Hier wird nicht mehr gerechnet, sondern mit der strafrechtlichen Keule zugeschlagen.</li></ol><h2 id="die-zangenbewegung" tabindex="-1">Die Zangenbewegung <a class="header-anchor" href="#die-zangenbewegung" aria-label="Permalink to &quot;Die Zangenbewegung&quot;">​</a></h2><p>Das Ziel ist offensichtlich: Wenn Schmid in einem Verfahren als Lügner „überführt“ wird, bricht sein Status als Kronzeuge in allen anderen Verfahren (Ibiza, Inserate, Postenschacher) wie ein Kartenhaus zusammen.</p><p>Es ist eine klassische Macht-Taktik: Schlägt man einen Kopf der Wahrheit ab, wachsen sofort zwei neue Klagen nach. Die Elite verteidigt ihre Pfründe nicht durch Transparenz, sondern durch eine juristische Materialschlacht, die jeden „Verräter“ (Kronzeugen) systematisch zerquetschen soll.</p><h2 id="bezug-zum-horten-mysterium" tabindex="-1">Bezug zum Horten-Mysterium <a class="header-anchor" href="#bezug-zum-horten-mysterium" aria-label="Permalink to &quot;Bezug zum Horten-Mysterium&quot;">​</a></h2><p>In der Geschichte der Arisierung sahen wir dasselbe Muster: Wer die besseren Anwälte und die richtigen Gutachter hatte, konnte Unrecht in Recht umdeuten. Michael Rami und Werner Suppan sind die modernen Architekten dieser Umdeutung.</p><p>Wir integrieren diese „Zangenbewegung“ als zentrales Handlungselement in <strong>Teil 4 unseres Drehbuchs</strong>. Die Hydra der Macht ist der Endgegner der Transparenz.</p><p><em>Der Index steigt. Die Hydra beißt. Wir dokumentieren alles.</em></p><hr><p>👈 <a href="/logbuch/">Zurück zum Logbuch</a> 🔮 <a href="/orakel.html">Das Orakel nach dem Schicksal der Hydra befragen</a></p>',15)])])}const m=n(t,[["render",s]]);export{l as __pageData,m as default};
